import pandas as pd
import requests
from datetime import datetime, timezone, timedelta

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

BASE = 'https://api.fda.gov/drug/event.json'

# Step 1: probe the API meta to find the latest date for which data is
# available.  openFDA's adverse-event dataset typically lags real-time
# by 90-150 days (quarterly refresh), so anchoring the search window
# to today's date returns 404 NOT_FOUND.  Anchor to last_updated and
# the script always returns the most recent 30 days the API has.
last_updated_iso = ''
try:
    meta_resp = requests.get(f'{BASE}?limit=1', timeout=20)
    if meta_resp.status_code == 200:
        last_updated_iso = (meta_resp.json().get('meta', {}) or {}).get('last_updated', '') or ''
except Exception:
    pass

if last_updated_iso:
    try:
        anchor = datetime.strptime(last_updated_iso, '%Y-%m-%d').replace(tzinfo=timezone.utc)
    except Exception:
        anchor = now - timedelta(days=120)
else:
    # Fall back to 120 days ago (covers typical openFDA quarterly lag).
    anchor = now - timedelta(days=120)

end_date = anchor.strftime('%Y%m%d')
start_date = (anchor - timedelta(days=30)).strftime('%Y%m%d')
data_age_days = max(0, (now.date() - anchor.date()).days)

# openFDA returns 404 + {error: NOT_FOUND, message: 'No matches found!'}
# when a search yields zero results.  Treat that as an empty result
# rather than letting raise_for_status crash the whole script.
def safe_count(url):
    try:
        r = requests.get(url, timeout=30)
    except Exception:
        return {}
    if r.status_code == 404:
        # openFDA's empty-result convention
        return {}
    if r.status_code != 200:
        return {}
    out = {}
    for row in (r.json().get('results') or []):
        term = row.get('term', '') or ''
        if term:
            out[term] = int(row.get('count', 0) or 0)
    return out

url_serious = (
    BASE + '?search=receivedate:[' + start_date + '+TO+' + end_date + ']'
    '+AND+serious:1'
    '&count=patient.drug.medicinalproduct.exact&limit=100'
)
url_death = (
    BASE + '?search=receivedate:[' + start_date + '+TO+' + end_date + ']'
    '+AND+seriousnessdeath:1'
    '&count=patient.drug.medicinalproduct.exact&limit=100'
)

serious_data = safe_count(url_serious)
death_data = safe_count(url_death)

all_drugs = sorted(set(list(serious_data.keys()) + list(death_data.keys())))
rows = []
for drug in all_drugs:
    s_count = serious_data.get(drug, 0)
    d_count = death_data.get(drug, 0)

    if s_count >= 500:
        volume_tier = 'VERY_HIGH'
    elif s_count >= 100:
        volume_tier = 'HIGH'
    elif s_count >= 25:
        volume_tier = 'MODERATE'
    else:
        volume_tier = 'LOW'

    death_pct = round(d_count / s_count * 100, 2) if s_count > 0 else 0.0

    if death_pct >= 10:
        severity = 'CRITICAL'
    elif death_pct >= 5:
        severity = 'HIGH'
    elif death_pct >= 1:
        severity = 'ELEVATED'
    else:
        severity = 'NORMAL'

    rows.append({
        'drug_name': drug,
        'serious_event_count': s_count,
        'death_report_count': d_count,
        'death_pct': death_pct,
        'volume_tier': volume_tier,
        'severity': severity,
        'report_window_start': start_date,
        'report_window_end': end_date,
        'report_window_days': 30,
        'data_age_days': data_age_days,
        'data_last_updated': last_updated_iso or 'unknown',
        '_epoch': now_epoch,
    })

output_columns = [
    'drug_name', 'serious_event_count', 'death_report_count', 'death_pct',
    'volume_tier', 'severity', 'report_window_start', 'report_window_end',
    'report_window_days', 'data_age_days', 'data_last_updated', '_epoch',
]
df = pd.DataFrame(rows, columns=output_columns)
if not df.empty:
    df = df.sort_values('serious_event_count', ascending=False).reset_index(drop=True)
GENERATE_RESULTS(df)
